head.script:
scwin.gVar = {
    "cMaxByteLength" : "",
    "cValueSource" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[secret > P > maxByteLength]<br/>Secret 컴포넌트에 입력 가능한 최대 Byte 수를 설정합니다.",
    "validation" : [
        "문자를 Byte 로 계산하여 입력 가능한 최대 Byte 를 숫자로 설정합니다.",
        "config.xml 의 WebSquare/byteCheckEncoding/@value 값을 기준으로 'euc-kr' 은 2Byte, 'utf-8' 은 3Byte 로 다국어 문자를 계산합니다.",
        "값을 설정하지 않으면 -1 로 적용되어 입력을 제한하지 않습니다.",
        "스크립트로 입력값을 설정하거나 ref 속성으로 바인딩된 데이터가 적용될때는 maxByteLength 가 적용되지 않습니다.",
        "maxByteLength 보다 초과된 문자는 컴포넌트의 입력창이 포커스 된 후 해제될때 처리됩니다.",
        "입력값을 붙여넣기하면 maxByteLength 보다 초과된 길이의 입력값은 입력 후 제거됩니다.",
        "maxBytelength 속성에 의해 초과 입력된 값이 제거될때 onblur 이벤트와 onfocus 이벤트가 한 번씩 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 기본값 설정
    con_maxByteLength.setValue("5");
    con_valueSource.setValue("setValue");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] target1 은 Secret 컴포넌트이며 Target 재생성 시 헬퍼가 초기값을 secret (6자 / 6Byte) 으로 설정합니다\n[절차] 위 조건 선택 -> Target 재생성 -> 검증 목적에 따라 아래 중 하나를 수행\n - Byte 계산 : target1 을 비우고 영문 또는 한글을 제한보다 길게 타이핑 -> 값 확인 버튼 클릭 (euc-kr 기준 한글 1자 2Byte)\n - 붙여넣기 : target1 을 비우고 제한보다 긴 값을 Ctrl+V 로 붙여넣기 -> 값 확인 버튼 클릭\n - 스크립트/ref 설정 : 값 설정 버튼 클릭 -> 값 확인 버튼 클릭 -> target1 클릭 후 다른 곳 클릭(포커스 해제) -> 값 확인 버튼 클릭\n - 이벤트 : clear 버튼으로 결과창을 비운 뒤 target1 에 제한을 넘겨 입력 -> 결과창에 쌓인 onfocus/onblur 발생 줄 확인\n[확인] password 라 화면으로 글자 수를 셀 수 없으므로 결과창의 값 길이와 Byte 수로 판정"', '', 'label1');

    // 조건 설정
    scwin.gVar["cMaxByteLength"] = con_maxByteLength.getValue();
    scwin.gVar["cValueSource"] = con_valueSource.getValue();

    let properties = {
        maxByteLength : scwin.gVar["cMaxByteLength"],
    }

    // ref 바인딩 방식 선택 시에만 ref 속성 부여 (바인딩 데이터는 초기화)
    if (scwin.gVar["cValueSource"] === "ref") {
        dm_ref.set("key1", "");
        properties.ref = "data:dm_ref.key1";
    }

    let cList = $c.gcm.createCList(properties);

    // 초과 입력값 제거 시 발생하는 onblur / onfocus 판정용 배선
    let eList = $c.gcm.createEList(["onfocus", "onblur"]);

    // comp 생성 함수 호출 (헬퍼가 생성 직후 setValue 로 6자 초기값 secret 설정)
    await $c.gcm.createBasicSecret(cList, eList);
}



// 미설정 표기 변환
scwin.fn_disp = function (strValue) {
    return (strValue === "") ? "미설정" : strValue;
}



// 현재 값의 길이 / Byte 수 표기 (password 라 화면으로 확인 불가)
scwin.fn_size = function () {
    let strValue = target1.getValue() || "";

    return "값 길이 " + strValue.length + " / Byte 수 " + WebSquare.util.getStringByteSize(strValue);
}



// 스크립트(setValue) 또는 ref 바인딩으로 maxByteLength 초과 값 설정 - validation 4 판정 출력
scwin.btn_setValue_onclick = function (e) {
    let strValue = "abcdefghijkl";

    if (scwin.gVar["cValueSource"] === "ref")
        dm_ref.set("key1", strValue);
    else
        target1.setValue(strValue);

    wf_body_bottom.getObj("scwin").setReturnValue("maxByteLength " + scwin.fn_disp(scwin.gVar["cMaxByteLength"]) + " / 설정 방식 " + scwin.gVar["cValueSource"] + " -> 설정 요청 값 Byte 수 : " + WebSquare.util.getStringByteSize(strValue) + " / 적용 후 target1 " + scwin.fn_size());
}



// 현재 입력값 확인 (타이핑/붙여넣기/포커스 해제 후 처리 확인) - validation 1, 2, 3, 5, 6 판정 출력
scwin.btn_getValue_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("maxByteLength " + scwin.fn_disp(scwin.gVar["cMaxByteLength"]) + " -> target1 " + scwin.fn_size());
}



// 초과 입력값 제거 시 발생하는 이벤트 - validation 7 판정 출력
scwin.target1_onfocus = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("onfocus 발생");
}



scwin.target1_onblur = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("onblur 발생");
}
